def transform(grid):
    h, w = len(grid), len(grid[0])

    # The background is the most frequent color.
    freq = {}
    for row in grid:
        for v in row:
            freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)

    # Find the largest 4-connected component of zeros: the panel.
    seen = set()
    best = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(comp) > len(best):
                best = comp

    r0 = min(r for r, c in best)
    r1 = max(r for r, c in best)
    c0 = min(c for r, c in best)
    c1 = max(c for r, c in best)
    ph, pw = r1 - r0 + 1, c1 - c0 + 1

    # Count outside objects by color, joining diagonally adjacent cells.
    panel = lambda r, c: r0 <= r <= r1 and c0 <= c <= c1
    seen = set()
    counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or panel(r, c) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                not panel(ny, nx) and
                                grid[ny][nx] == color and
                                (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            counts[color] = counts.get(color, 0) + 1

    out = [[0] * pw for _ in range(ph)]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            color = grid[r][c]
            if color == 0:
                continue
            y, x = r - r0, c - c0
            for k in range(counts.get(color, 0)):
                xx = x + 2 * k
                if xx < pw:
                    out[y][xx] = color
    return out

def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The color legend is a two-column table near the lower-left.
    best_col, best_score = 0, -1
    for c in range(min(w - 1, w // 3 + 1)):
        score = sum(
            grid[r][c] != bg and grid[r][c + 1] != bg
            for r in range(h // 2, h)
        )
        if score > best_score:
            best_col, best_score = c, score

    palette = set()
    mappings = []
    for r in range(h // 2, h):
        source, target = grid[r][best_col], grid[r][best_col + 1]
        if source != bg:
            mappings.append((source, target))
            palette.add((r, best_col))
        if target != bg:
            palette.add((r, best_col + 1))

    # Find same-color connected components outside the legend.
    unseen = {
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] != bg and (r, c) not in palette
    }
    components = {}
    while unseen:
        start = unseen.pop()
        color = grid[start[0]][start[1]]
        cells = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                p = (nr, nc)
                if p in unseen and grid[nr][nc] == color:
                    unseen.remove(p)
                    cells.add(p)
                    stack.append(p)
        components.setdefault(color, []).append(cells)

    # Each pair of opposite L-shaped markers defines a rectangle.
    rectangles = {}
    for color, groups in components.items():
        ls = []
        for cells in groups:
            if len(cells) != 3:
                continue
            rs = [r for r, c in cells]
            cs = [c for r, c in cells]
            if max(rs) - min(rs) != 1 or max(cs) - min(cs) != 1:
                continue
            corners = {
                (min(rs), min(cs)), (min(rs), max(cs)),
                (max(rs), min(cs)), (max(rs), max(cs))
            }
            missing = list(corners - cells)
            if len(missing) == 1:
                m = missing[0]
                orientation = (m[0] == max(rs), m[1] == max(cs))
                ls.append((cells, orientation))

        used = set()
        rects = []
        for i in range(len(ls)):
            if i in used:
                continue
            for j in range(i + 1, len(ls)):
                if j in used:
                    continue
                a, oa = ls[i]
                b, ob = ls[j]
                if oa[0] != ob[0] and oa[1] != ob[1]:
                    anchors = a | b
                    rects.append((
                        anchors,
                        min(r for r, c in anchors),
                        max(r for r, c in anchors),
                        min(c for r, c in anchors),
                        max(c for r, c in anchors),
                    ))
                    used.update((i, j))
                    break
        if rects:
            rectangles[color] = rects

    out = [row[:] for row in grid]

    # Apply the legend from bottom to top so nested rectangles layer correctly.
    for source, target in reversed(mappings):
        for anchors, r0, r1, c0, c1 in rectangles.get(source, []):
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = target
            for r, c in anchors:
                out[r][c] = source

    return out

from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comp_at = [[-1] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            idx = len(comps)
            for y, x in cells:
                comp_at[y][x] = idx
            comps.append({
                "color": color,
                "cells": cells,
                "r0": min(y for y, x in cells),
                "r1": max(y for y, x in cells),
                "c0": min(x for y, x in cells),
                "c1": max(x for y, x in cells),
                "size": len(cells),
            })

    objects = [i for i, comp in enumerate(comps) if comp["size"] == 4]
    markers = [i for i, comp in enumerate(comps) if comp["size"] == 1]
    markers.sort(key=lambda i: comps[i]["cells"][0][1])
    sequence = [comps[i]["color"] for i in markers]

    if not objects or len(sequence) != len(objects):
        return [row[:] for row in grid]

    centers = {}
    tiles = {}
    for i in objects:
        obj = comps[i]
        centers[i] = ((obj["r0"] + obj["r1"]) / 2,
                      (obj["c0"] + obj["c1"]) / 2)

        votes = Counter()
        neighbors = []
        for r, c in obj["cells"]:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and comp_at[nr][nc] != i:
                    votes[grid[nr][nc]] += 1
                    neighbors.append((nr, nc))
        frame_color = votes.most_common(1)[0][0]
        frame_components = Counter(
            comp_at[r][c] for r, c in neighbors
            if grid[r][c] == frame_color
        )
        tiles[i] = comps[frame_components.most_common(1)[0][0]]

    xs = sorted(set(x for y, x in centers.values()))
    ys = sorted(set(y for y, x in centers.values()))
    dxs = [b - a for a, b in zip(xs, xs[1:])]
    dys = [b - a for a, b in zip(ys, ys[1:])]
    x_limit = 1.5 * min(dxs) if dxs else 0
    y_limit = 1.5 * min(dys) if dys else 0

    adjacent = {i: set() for i in objects}
    for i in objects:
        y1, x1 = centers[i]
        for j in objects:
            if i == j:
                continue
            y2, x2 = centers[j]
            if abs(y1 - y2) < 0.01 and abs(x1 - x2) <= x_limit:
                adjacent[i].add(j)
            if abs(x1 - x2) < 0.01 and abs(y1 - y2) <= y_limit:
                adjacent[i].add(j)

    def find_path(pos, prev, used, path):
        if pos == len(sequence):
            return path
        for i in objects:
            if i in used or comps[i]["color"] != sequence[pos]:
                continue
            if prev is not None and i not in adjacent[prev]:
                continue
            result = find_path(pos + 1, i, used | {i}, path + [i])
            if result is not None:
                return result
        return None

    path = find_path(0, None, set(), [])
    if path is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for a, b in zip(path, path[1:]):
        oa, ob = comps[a], comps[b]
        ta, tb = tiles[a], tiles[b]
        ya, xa = centers[a]
        yb, xb = centers[b]

        if abs(ya - yb) < 0.01:
            lo, hi = sorted((xa, xb))
            start = ta["c1"] + 1 if xa < xb else tb["c1"] + 1
            end = tb["c0"] - 1 if xa < xb else ta["c0"] - 1
            for r in range(oa["r0"], oa["r1"] + 1):
                for c in range(start, end + 1):
                    out[r][c] = oa["color"]
        else:
            start = ta["r1"] + 1 if ya < yb else tb["r1"] + 1
            end = tb["r0"] - 1 if ya < yb else ta["r0"] - 1
            for r in range(start, end + 1):
                for c in range(oa["c0"], oa["c1"] + 1):
                    out[r][c] = oa["color"]

    return out

