    return g

def transform(grid):
    out = [row[:] for row in grid]
    cols = [2, 7, 12, 17]
    body_rows = [8, 13, 18, 23]

    def signature(r, c):
        vals = [grid[i][j] for i in range(r, r + 3) for j in range(c, c + 3)]
        colored = [v for v in vals if v != 8]
        if not colored:
            return None
        return (colored[0], len(colored))

    keys = {signature(1, c) for c in cols}
    keys.discard(None)

    targets = set()
    for ri, r in enumerate(body_rows):
        for ci, c in enumerate(cols):
            if signature(r, c) in keys:
                targets.add((ri, ci))
                for i in range(r - 1, r + 4):
                    for j in range(c - 1, c + 4):
                        if out[i][j] == 8:
                            out[i][j] = 3

    special = any(
        all((r, c) in targets for c in range(4)) for r in range(4)
    ) or any(
        all((r, c) in targets for r in range(4)) for c in range(4)
    )

    if special:
        for r in range(5):
            for c in range(len(out[r])):
                if out[r][c] == 8:
                    out[r][c] = 3

    marker = 3 if special else 2
    for r in (28, 29):
        for c in range(len(out[r])):
            out[r][c] = marker

    return out

from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if not zeros:
        return [row[:] for row in grid]

    r0 = min(r for r, c in zeros)
    c0 = min(c for r, c in zeros)
    oh = max(r for r, c in zeros) - r0 + 1
    ow = max(c for r, c in zeros) - c0 + 1

    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    target = None
    if twos:
        tr = min(r for r, c in twos)
        tc = min(c for r, c in twos)
        th = max(r for r, c in twos) - tr + 1
        tw = max(c for r, c in twos) - tc + 1
        if th == oh and tw == ow and len(twos) == th * tw:
            target = (tr, tc)

    def fits(r, c):
        if r < 0 or c < 0 or r + oh > h or c + ow > w:
            return False
        return all(grid[y][x] in (0, 1, 2)
                   for y in range(r, r + oh)
                   for x in range(c, c + ow))

    start = (r0, c0)
    dist = {start: 0}
    queue = deque([start])
    while queue:
        r, c = queue.popleft()
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nxt = (r + dr, c + dc)
            if nxt not in dist and fits(*nxt):
                dist[nxt] = dist[(r, c)] + 1
                queue.append(nxt)

    end = target if target in dist else max(dist, key=dist.get)
    out = [row[:] for row in grid]
    for r, c in zeros:
        out[r][c] = 1
    er, ec = end
    for r in range(er, er + oh):
        for c in range(ec, ec + ow):
            out[r][c] = 0
    return out

def transform(grid):
    from collections import Counter
    from math import floor, ceil

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != bg and c != 2]
    if not colors:
        return [row[:] for row in grid]
    fg = max(colors, key=lambda c: counts[c])

    def components(color):
        seen = set()
        result = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                comp = []
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        q = (y + dy, x + dx)
                        if (0 <= q[0] < h and 0 <= q[1] < w
                                and q not in seen and grid[q[0]][q[1]] == color):
                            seen.add(q)
                            stack.append(q)
                result.append(comp)
        return result

    markers = components(2)
    objects = components(fg)

    def bounds(comp):
        rs = [p[0] for p in comp]
        cs = [p[1] for p in comp]
        return min(rs), max(rs), min(cs), max(cs)

    mb = [bounds(comp) for comp in markers]
    ob = [bounds(comp) for comp in objects]

    # Pair markers to objects when their centers share a row or column.
    candidates = []
    for i, (r0, r1, c0, c1) in enumerate(mb):
        mr, mc = (r0 + r1) / 2, (c0 + c1) / 2
        for j, (a, b, x, y) in enumerate(ob):
            orow, ocol = (a + b) / 2, (x + y) / 2
            if mc == ocol and mr != orow:
                candidates.append((abs(mr - orow), i, j, "v"))
            if mr == orow and mc != ocol:
                candidates.append((abs(mc - ocol), i, j, "h"))

    candidates.sort()
    paired_markers = set()
    paired_objects = set()
    moves = []
    for _, i, j, axis in candidates:
        if i in paired_markers or j in paired_objects:
            continue
        paired_markers.add(i)
        paired_objects.add(j)
        moves.append((i, j, axis))

    out = [row[:] for row in grid]
    for comp in markers:
        for r, c in comp:
            out[r][c] = bg

    for i, j, axis in moves:
        comp = markers[i]
        r0, r1, c0, c1 = mb[i]
        a, b, x, y = ob[j]

        if axis == "v":
            target = (a + b) / 2
            center = (r0 + r1) / 2
            if center < target:
                new_r0 = floor(target) - (r1 - r0)
            else:
                new_r0 = ceil(target)
            dr, dc = new_r0 - r0, 0
        else:
            target = (x + y) / 2
            center = (c0 + c1) / 2
            if center < target:
                new_c0 = floor(target) - (c1 - c0)
            else:
                new_c0 = ceil(target)
            dr, dc = 0, new_c0 - c0

        steps = max(abs(dr), abs(dc))
        sr = 0 if dr == 0 else (1 if dr > 0 else -1)
        sc = 0 if dc == 0 else (1 if dc > 0 else -1)

        for t in range(steps):
            for r, c in comp:
                out[r + sr * t][c + sc * t] = 0
        for r, c in comp:
            out[r + dr][c + dc] = 2

    return out

from collections import Counter, deque

def transform(grid):
    H, W = len(grid), len(grid[0])

    # Prefix sums for each color, used to evaluate candidate two-color panels.
    pref = {}
    for color in range(10):
        p = [[0] * (W + 1) for _ in range(H + 1)]
        for r in range(H):
            for c in range(W):
                p[r + 1][c + 1] = (
                    p[r][c + 1] + p[r + 1][c] - p[r][c]
                    + (grid[r][c] == color)
                )
        pref[color] = p

    def rect_sum(color, r1, c1, r2, c2):
        p = pref[color]
        return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1]

    candidates = []
    for a in range(10):
        for b in range(a + 1, 10):
            for top in range(H):
                valid = [True] * W
                for bot in range(top, H):
                    for c in range(W):
                        if grid[bot][c] not in (a, b):
                            valid[c] = False

                    c = 0
                    while c < W:
                        if not valid[c]:
                            c += 1
                            continue
                        left = c
                        while c < W and valid[c]:
                            c += 1
                        right = c - 1

                        for l in range(left, right + 1):
                            for rr in range(l, right + 1):
                                area = (bot - top + 1) * (rr - l + 1)
                                if area < 20:
                                    continue
                                na = rect_sum(a, top, l, bot, rr)
                                nb = area - na
                                if na == 0 or nb == 0:
                                    continue
                                base = a if na > nb else b
                                base_count = na if base == a else nb
                                if base_count < area * 0.55:
                                    continue

                                width = rr - l + 1
                                height = bot - top + 1
                                if rect_sum(base, top, l, top, rr) < (width + 1) // 2:
                                    continue
                                if rect_sum(base, bot, l, bot, rr) < (width + 1) // 2:
                                    continue
                                if rect_sum(base, top, l, bot, l) < (height + 1) // 2:
                                    continue
                                if rect_sum(base, top, rr, bot, rr) < (height + 1) // 2:
                                    continue

                                candidates.append((area, base_count, top, l, bot, rr, base,
                                                   b if base == a else a))

    if not candidates:
        return grid

    _, _, top, left, bottom, right, base, hole = max(candidates)
    panel = [row[left:right + 1] for row in grid[top:bottom + 1]]
    ph, pw = len(panel), len(panel[0])

    # A panel shorter than it is wide gives the upper half of a vertically
    # reflected design; a square panel is already complete.
    if ph < pw:
        full = panel + panel[-2::-1]
    else:
        full = [row[:] for row in panel]

    out_h, out_w = len(full), len(full[0])
    mask = [[full[r][c] != base for c in range(out_w)] for r in range(out_h)]

    def canonical(cells):
        points = list(cells)
        forms = []
        for reflect in (1, -1):
            for rot in range(4):
                transformed = []
                for r, c in points:
                    x, y = r, c * reflect
                    for _ in range(rot):
                        x, y = y, -x
                    transformed.append((x, y))
                mr = min(x for x, y in transformed)
                mc = min(y for x, y in transformed)
                forms.append(tuple(sorted((x - mr, y - mc) for x, y in transformed)))
        return min(forms)

    # Find connected components of the outside objects, excluding the panel.
    panel_cells = {(r, c) for r in range(top, bottom + 1)
                   for c in range(left, right + 1)}
    seen = set()
    shape_colors = Counter()
    color_totals = Counter()
    for r in range(H):
        for c in range(W):
            color = grid[r][c]
