                    nx, ny = x + dx, y + dy
                    if (0 <= nx < H and 0 <= ny < W and
                        (nx, ny) not in panel_cells and
                        (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            sig = canonical([(x - r, y - c) for x, y in comp])
            shape_colors[(sig, color)] += 1
