    # Fill each stencil component with the most common matching object color.
    seen_mask = set()
    for r in range(out_h):
        for c in range(out_w):
            if not mask[r][c] or (r, c) in seen_mask:
                continue
            q = [(r, c)]
            seen_mask.add((r, c))
            comp = []
            while q:
                x, y = q.pop()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < out_h and 0 <= ny < out_w and
                        mask[nx][ny] and (nx, ny) not in seen_mask):
                        seen_mask.add((nx, ny))
                        q.append((nx, ny))

            sig = canonical([(x - r, y - c) for x, y in comp])
            votes = Counter()
            for (shape, color), count in shape_colors.items():
                if shape == sig:
                    votes[color] += count
            if votes:
                color = max(votes, key=lambda v: (votes[v], color_totals[v]))
                for x, y in comp:
                    full[x][y] = color

    return full

