def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find connected components of color 1.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != 1 or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            g[ny][nx] == 1 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    # For each object, extend any colored strip touching its boundary.
    for comp in components:
        ports = []

        # Each tuple is (direction, first position outside object, cross-section).
        for direction in ("up", "down", "left", "right"):
            by_line = {}
            if direction in ("up", "down"):
                cols = {c for r, c in comp}
                for c in cols:
                    cells = [r for r, x in comp if x == c]
                    edge = min(cells) if direction == "up" else max(cells)
                    start = edge - 1 if direction == "up" else edge + 1
                    if 0 <= start < h and g[start][c] not in (1, 8):
                        by_line.setdefault(start, []).append(c)
            else:
                rows = {r for r, c in comp}
                for r in rows:
                    cells = [c for y, c in comp if y == r]
                    edge = min(cells) if direction == "left" else max(cells)
                    start = edge - 1 if direction == "left" else edge + 1
                    if 0 <= start < w and g[r][start] not in (1, 8):
                        by_line.setdefault(start, []).append(r)

            for start, cross_values in by_line.items():
                cross_values.sort()
                groups = []
                group = []
                for v in cross_values:
                    if group and v != group[-1] + 1:
                        groups.append(group)
                        group = []
                    group.append(v)
                if group:
                    groups.append(group)
                for group in groups:
                    ports.append((direction, start, group))

        for direction, start, cross in ports:
            if direction == "up":
                step = -1
                limit = start + 1
                def cells_at(k):
                    return [(start - k, x) for x in cross]
            elif direction == "down":
                step = 1
                limit = h - start
                def cells_at(k):
                    return [(start + k, x) for x in cross]
            elif direction == "left":
                step = -1
                limit = start + 1
                def cells_at(k):
                    return [(x, start - k) for x in cross]
            else:
                step = 1
                limit = w - start
                def cells_at(k):
                    return [(x, start + k) for x in cross]

            pattern = []
            run = 0
            for k in range(limit):
                coords = cells_at(k)
                vals = [g[y][x] for y, x in coords]
                if any(v in (1, 8) for v in vals):
                    break
                pattern.append(vals)
                run += 1

            if not pattern:
                continue

            # Continue the observed sequence away from the object, replacing
            # any crossing colored strip along the way.
            for k in range(run, limit):
                coords = cells_at(k)
                if any(g[y][x] == 1 for y, x in coords):
                    break
                vals = pattern[k % len(pattern)]
                for (y, x), value in zip(coords, vals):
                    g[y][x] = value

    return g

