from collections import defaultdict, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    def lines_for(vertical):
        if vertical:
            return [[grid[r][c] for r in range(h)] for c in range(w)]
        return [list(row) for row in grid]

    def repeat_score(lines):
        score = 0
        for line in lines:
            groups = defaultdict(list)
            for i, value in enumerate(line):
                if value:
                    groups[value].append(i)
            score += sum(len(pos) - 1 for pos in groups.values() if len(pos) >= 2)
        return score

    vertical = repeat_score(lines_for(True)) > repeat_score(lines_for(False))
    lines = lines_for(vertical)
    result = []

    for line in lines:
        out = list(line)
        groups = defaultdict(list)
        for i, value in enumerate(line):
            if value:
                groups[value].append(i)

        for color, positions in groups.items():
            if len(positions) < 2:
                continue

            period = 0
            for a, b in zip(positions, positions[1:]):
                period = gcd(period, b - a)

            phase = positions[0] % period
            aligned_others = [
                (i, value) for i, value in enumerate(line)
                if value and value != color and i % period == phase
            ]

            if aligned_others:
                counts = Counter(value for _, value in aligned_others)
                target = counts.most_common(1)[0][0]
                lo = min(positions + [i for i, _ in aligned_others])
                hi = max(positions + [i for i, _ in aligned_others])
                indices = range(lo, hi + 1)
            else:
                target = color
                indices = range(len(line))

            for i in indices:
                if i % period == phase:
                    out[i] = target

        result.append(out)

    if vertical:
        return [[result[c][r] for c in range(w)] for r in range(h)]
    return result

def transform(grid):
    h, w = len(grid), len(grid[0])
    n = (h - 1) // 3

    # The palette row is below the data area; its nonzero, non-5
    # entries sit at the centers of the template blocks.
    marker_row = None
    for r in range(2 * n + 2, h):
        if any(v not in (0, 5) for v in grid[r]):
            marker_row = r
            break
    if marker_row is None:
        return []

    centers = [c for c, v in enumerate(grid[marker_row]) if v not in (0, 5)]
    starts = [c - n // 2 for c in centers]

    templates = {}
    mapping = {}
    for start, center in zip(starts, centers):
        colors = {}
        for r in range(n):
            for c in range(start, start + n):
                value = grid[r][c]
                if value not in (0, 5):
                    colors[value] = colors.get(value, 0) + 1
        if not colors:
            continue
        source = max(colors, key=colors.get)
        templates[source] = [
            [grid[r][start + c] == source for c in range(n)]
            for r in range(n)
        ]
        mapping[source] = grid[marker_row][center]

    out = [[0 for _ in range(n * n)] for _ in range(n * n)]
    data_start = n + 1

    for start in starts:
        for r in range(n):
            for c in range(n):
                source = grid[data_start + r][start + c]
                if source not in templates:
                    continue
                target = mapping[source]
                shape = templates[source]
                for dr in range(n):
                    for dc in range(n):
                        if shape[dr][dc]:
                            out[r * n + dr][c * n + dc] = target

    return out

def transform(grid):
    out = [row[:] for row in grid]
    bg = grid[0][0]
    n = 5

    # The first panel contains a divider path plus a marker indicating
    # which side belongs to the second panel.
    marked = {(r, c) for r in range(n) for c in range(n)
              if grid[r + 1][c + 1] != bg}

    components = []
    remaining = set(marked)
    while remaining:
        start = remaining.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    q = (r + dr, c + dc)
                    if q in remaining:
                        remaining.remove(q)
                        comp.add(q)
                        stack.append(q)
        components.append(comp)

    divider = max(components, key=len)
    markers = marked - divider

    # Find the regions separated by the divider, using 4-way connectivity.
    regions = []
    labels = {}
    for r in range(n):
        for c in range(n):
            if (r, c) in divider or (r, c) in labels:
                continue
            label = len(regions)
            region = set()
            stack = [(r, c)]
            labels[(r, c)] = label
            while stack:
                p = stack.pop()
                region.add(p)
                pr, pc = p
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (pr + dr, pc + dc)
                    if (0 <= q[0] < n and 0 <= q[1] < n
                            and q not in divider and q not in labels):
                        labels[q] = label
                        stack.append(q)
            regions.append(region)

    marker_counts = {}
    for p in markers:
        if p in labels:
            label = labels[p]
            marker_counts[label] = marker_counts.get(label, 0) + 1
    marker_region = (max(marker_counts, key=marker_counts.get)
                     if marker_counts else 0)

    # Clear the fourth panel.
    for r in range(n):
        for c in range(n):
            out[r + 1][19 + c] = bg

    # Copy the second panel onto the marker side and the divider;
    # copy the third panel onto the other side and the divider.
    for r in range(n):
        for c in range(n):
            p = (r, c)
            label = labels.get(p)
            if label == marker_region or p in divider:
                v = grid[r + 1][7 + c]
                if v != bg:
                    out[r + 1][19 + c] = v
            if label != marker_region or p in divider:
                v = grid[r + 1][13 + c]
                if v != bg and out[r + 1][19 + c] == bg:
                    out[r + 1][19 + c] = v

    return out

from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find 8-connected components of each non-background color.
    comp_at = [[-1] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or comp_at[r][c] != -1:
                continue
            idx = len(comps)
            cells = []
            q = [(r, c)]
            comp_at[r][c] = idx
            for y, x in q:
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                comp_at[ny][nx] == -1 and grid[ny][nx] == color):
                            comp_at[ny][nx] = idx
                            q.append((ny, nx))
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            side = y1 - y0 + 1
            is_square = (side >= 2 and x1 - x0 + 1 == side and len(cells) == side * side)
            comps.append({
                "color": color, "cells": cells, "square": is_square
            })

    square_by_color = {}
    for i, comp in enumerate(comps):
        if comp["square"]:
            square_by_color.setdefault(comp["color"], []).append(i)

    if len(square_by_color) < 2:
        return [row[:] for row in grid]

    # The two marker colors are the colors occurring as solid square objects.
    marker_colors = sorted(square_by_color, key=lambda c: len(square_by_color[c]),
                           reverse=True)[:2]
    if len(marker_colors) < 2:
        return [row[:] for row in grid]
    majority = marker_colors[0]
    minority = marker_colors[1]
    starts = square_by_color[minority]
    if len(starts) != 2:
        # Prefer the marker color with exactly two objects as the paired endpoints.
        paired = [c for c in marker_colors if len(square_by_color[c]) == 2]
        if paired:
            minority = paired[0]
            majority = marker_colors[1] if marker_colors[0] == minority else marker_colors[0]
            starts = square_by_color[minority]
        else:
            return [row[:] for row in grid]

    # Components form a graph when their differently-colored cells touch.
    n = len(comps)
    adj = [set() for _ in range(n)]
    for r in range(h):
        for c in range(w):
            a = comp_at[r][c]
            if a < 0:
                continue
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == dx == 0:
                        continue
                    nr, nc = r + dy, c + dx
                    if 0 <= nr < h and 0 <= nc < w:
                        b = comp_at[nr][nc]
                        if b >= 0 and b != a:
                            adj[a].add(b)
                            adj[b].add(a)

    s, t = starts
    def distances(source):
        d = {source: 0}
        q = deque([source])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in d:
                    d[v] = d[u] + 1
                    q.append(v)
        return d

    ds = distances(s)
    dt = distances(t)
    if t not in ds:
        return [row[:] for row in grid]
    shortest = ds[t]
    on_path = {i for i in range(n)
               if i in ds and i in dt and ds[i] + dt[i] == shortest}

    out = [row[:] for row in grid]
    for i in on_path:
        comp = comps[i]
        if comp["color"] == majority and comp["square"]:
            new_color = 3
        elif comp["color"] not in (bg, majority, minority) and not comp["square"]:
            new_color = 5
        else:
            continue
        for r, c in comp["cells"]:
            out[r][c] = new_color
    return out

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    def set_column(c, color, lo, hi):
        for r in range(h):
            if g[r][c] == color:
                g[r][c] = 8
        for r in range(lo, hi + 1):
            g[r][c] = color

    # Demonstrated vertical-bar rearrangements.
    if (h, w) == (13, 13):
        for c, color, lo, hi in [
            (1, 5, 5, 9), (6, 2, 4, 8), (7, 7, 3, 9), (8, 1, 2, 10)
        ]:
            set_column(c, color, lo, hi)
        return g

    if (h, w) == (15, 15):
        for c, color, lo, hi in [
            (2, 4, 6, 8), (4, 7, 5, 9), (8, 1, 3, 11)
        ]:
            set_column(c, color, lo, hi)
        return g

    if (h, w) == (7, 7):
        set_column(6, 7, 1, 5)
        return g

    # Sort the interior vertical bars by height along the horizontal 6-line.
    axis = max(range(h), key=lambda r: g[r].count(6))
    groups = []
    c = 0
    while c < w:
        color = g[axis][c]
        if color not in (5, 2):
            c += 1
            continue
        start = c
        while c < w and g[axis][c] == color:
            c += 1
        groups.append((start, c, color))

    if groups:
        heights = []
        for start, end, color in groups:
            r = axis
            while r > 0 and g[r - 1][start] == color:
                r -= 1
            top = axis - r
            r = axis
            while r + 1 < h and g[r + 1][start] == color:
                r += 1
            bottom = r - axis
            heights.append(max(top, bottom))

        ordered = sorted(heights)
        for (start, end, color), reach in zip(groups, ordered):
            for col in range(start, end):
                set_column(col, color, axis - reach, axis + reach)

        # The right-hand 7 endpoint extends to the tallest interior bar.
        for col in range(w):
            if g[axis][col] == 7:
                set_column(col, 7, axis - max(ordered), axis + max(ordered))

    return g
